<# 
    Invoke-RemoteReboot.ps1
    Reboots a remote host using PowerShell Remoting (PSRemoting)
    Requirements: PSRemoting must be enabled on the remote host
    Note: This script requires WinRM to be configured and authenticated
#>

param(
    [string]$ComputerName = 'remote-host',
    [PSCredential]$Credential,
    [switch]$Verbose
)

function Reboot-RemoteHost {
    try {
        if ($Verbose) {
            Write-Host 'Verifying remote connection...' -ForegroundColor Cyan
        }

        # Attempt reboot with force to ensure immediate restart
        Invoke-Command -ComputerName $ComputerName -Credential $Credential -ErrorAction Stop {
            param($ComputerName)
            Write-Host "Rebooting computer: $ComputerName" -ForegroundColor Green
            Restart-Computer -Force
        }

        Write-Host 'Remote reboot initiated successfully.' -ForegroundColor Green
    } catch {
        Write-Host 'Error initiating remote reboot:' -ForegroundColor Red
        Write-Error $_.Exception.Message
    }
}

# Main execution
if ($Credential) {
    Reboot-RemoteHost -Credential $Credential
} else {
    Write-Warning 'No credentials provided. PowerShell Remoting may not work without proper authentication.'
    Reboot-RemoteHost
}
